  if ("'!found || JSON.stringify(found.locations) !== JSON.stringify(file.locations)) mismatch++;
}
console.log('"'plan_groups=' + expected + ' report_groups=' + report.entity_repairs.length + ' location_mismatches=' + mismatch);
process.exitCode = mismatch || expected "'!== report.entity_repairs.length ? 1 : 0;
NODE'

